$id=filter_input(INPUT_GET,"id",FILTER_VALIDATE_INT);if(!$id){header("Location: dashboard.php?error=1");exit;}
$q=mysqli_prepare($conn,"SELECT * FROM projects WHERE id=?");mysqli_stmt_bind_param($q,"i",$id);mysqli_stmt_execute($q);$project=mysqli_fetch_assoc(mysqli_stmt_get_result($q));mysqli_stmt_close($q);if(!$project){header("Location: dashboard.php?error=1");exit;}
if($_SERVER["REQUEST_METHOD"]==="POST"){
 if(!admin_csrf_valid()){header("Location: edit_project.php?id=$id&error=1");exit;}
 $title=trim($_POST["title"]??"");$description=trim($_POST["description"]??"");$program=trim($_POST["program"]??"");$calls=trim($_POST["calls"]??"");$duration=($_POST["duration"]??"")===""?null:filter_var($_POST["duration"],FILTER_VALIDATE_INT);$budget=($_POST["budget"]??"")===""?null:filter_var($_POST["budget"],FILTER_VALIDATE_FLOAT);$institution=trim($_POST["institution"]??"");$country=trim($_POST["country"]??"");$contact=trim($_POST["contact"]??"");
 if(!$title||!$description||!$program||!$calls||$duration===false||($duration!==null&&$duration<1)||$budget===false||($budget!==null&&$budget<0)){header("Location: edit_project.php?id=$id&error=1");exit;}
 $q=mysqli_prepare($conn,"UPDATE projects SET title=?,duration=?,description=?,budget=?,program=?,calls=?,institution=?,country=?,contact=? WHERE id=?");mysqli_stmt_bind_param($q,"sisdsssssi",$title,$duration,$description,$budget,$program,$calls,$institution,$country,$contact,$id);$ok=mysqli_stmt_execute($q);mysqli_stmt_close($q);header("Location: dashboard.php?".($ok?"saved=1":"error=1"));exit;
}
